/**
 * Native UI contract for generated web-to-SWT Grid and Tree declarations.
 * Runs only under the original Tycho SWT UI harness, on the Display thread.
 * No browser/RAP session or graphics/pixel equivalence is implied.
 */
public class GridWebNativeMapping_Test {
    private Display display;
    private Shell shell;

    @Before
    public void setUp() {
        display = Display.getDefault();
        shell = new Shell(display);
    }

    @After
    public void tearDown() {
        if (shell != null && !shell.isDisposed()) shell.dispose();
    }

    @Test
    public void nativeNebulaGridOwnsRowsAndPreservesWebText() {
        Composite root = GridNativeWebUiBinder.create(shell);
        assertEquals(4, root.getChildren().length);
        Control header = root.getChildren()[0];
        assertTrue(header instanceof Label);
        assertEquals("Orders && inventory — 日本語", ((Label) header).getText());
        assertEquals("heading", header.getData("web.field"));

        Control candidate = root.getChildren()[2];
        assertTrue(candidate instanceof Grid);
        Grid grid = (Grid) candidate;
        assertSame(root, grid.getParent());
        assertEquals("orders", grid.getData("web.field"));
        assertEquals(2, grid.getColumnCount());
        assertEquals("Order", grid.getColumn(0).getText());
        assertEquals("Status", grid.getColumn(1).getText());
        assertEquals(2, grid.getItemCount());
        assertEquals("A-01", grid.getItem(0).getText(0));
        assertEquals("Queued", grid.getItem(0).getText(1));
        assertEquals("B-02", grid.getItem(1).getText(0));
        assertEquals("Shipped", grid.getItem(1).getText(1));
        assertFalse(root.isDisposed());
        root.setSize(new Point(600, 350));
        root.layout(true);
    }

    @Test
    public void nativeSwtTreeUsesItemsNotControls() {
        Composite root = TreeNativeWebUiBinder.create(shell);
        assertEquals(2, root.getChildren().length);
        assertEquals("Archive && tools", ((Label) root.getChildren()[0]).getText());
        Control candidate = root.getChildren()[1];
        assertTrue(candidate instanceof Tree);
        Tree tree = (Tree) candidate;
        assertSame(root, tree.getParent());
        assertEquals("folders", tree.getData("web.field"));
        assertEquals(2, tree.getItemCount());
        TreeItem branch = tree.getItem(0);
        assertEquals("Projects & files", branch.getText());
        assertEquals("root", branch.getData("web.field"));
        assertTrue(branch.getExpanded());
        assertEquals(2, branch.getItemCount());
        TreeItem documents = branch.getItem(0);
        assertSame(branch, documents.getParentItem());
        assertEquals("docs", documents.getData("web.field"));
        assertEquals("Report.txt", documents.getItem(0).getText());
        assertEquals("Recent", tree.getItem(1).getText());
        assertFalse(tree.isDisposed());
    }

@Test
public void staticProgressUsesNativeRwtCompatibleIntegerRange() {
    Composite root = StaticProgressNativeWebUiBinder.create(shell);
    assertEquals(1, root.getChildren().length);
    assertTrue(root.getChildren()[0] instanceof Composite);
    Composite section = (Composite) root.getChildren()[0];
    assertEquals(4, section.getChildren().length);
    assertTrue(section.getChildren()[1] instanceof ProgressBar);
    ProgressBar sync = (ProgressBar) section.getChildren()[1];
    assertSame(section, sync.getParent());
    assertEquals("sync", sync.getData("web.field"));
    assertEquals(100, sync.getMaximum());
    assertEquals(63, sync.getSelection());
    ProgressBar completed = (ProgressBar) section.getChildren()[2];
    assertEquals(1, completed.getMaximum());
    assertEquals(1, completed.getSelection());
    ProgressBar empty = (ProgressBar) section.getChildren()[3];
    assertEquals(999999, empty.getMaximum());
    assertEquals(0, empty.getSelection());
    assertFalse(root.isDisposed());
}

    @Test
    public void parentDisposalReleasesBothNativeWidgetTrees() {
        Composite gridRoot = GridNativeWebUiBinder.create(shell);
        Composite treeRoot = TreeNativeWebUiBinder.create(shell);
        Composite progressRoot = StaticProgressNativeWebUiBinder.create(shell);
        Grid grid = (Grid) gridRoot.getChildren()[2];
        Tree tree = (Tree) treeRoot.getChildren()[1];
        shell.dispose();
        assertTrue(gridRoot.isDisposed());
        assertTrue(treeRoot.isDisposed());
        assertTrue(progressRoot.isDisposed());
        assertTrue(grid.isDisposed());
        assertTrue(tree.isDisposed());
    }
}
